-- Data migration script for system_settings
-- Migrating data from Cassandra to PostgreSQL

-- Insert system settings data based on the CSV attachment
ON CONFLICT (id) DO UPDATE SET
    field = EXCLUDED.field,
    value = EXCLUDED.value,
    updated_date = CURRENT_TIMESTAMP;

-- Verify the data migration
SELECT COUNT(*) as total_records FROM sunbird.system_settings;
SELECT id, field, LEFT(value, 100) as value_preview FROM sunbird.system_settings ORDER BY id;